fn argmax(arr: &Vec<i8>) -> usize {
    // The array is guaranteed to be non-empty, so we can safely unwrap
    arr.iter()
        .enumerate()
        .max_by_key(|&(_, &value)| value)
        .map(|(index, _)| index)
        .unwrap()
}

